export const escapeHtml = s => String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeHtml;
const title=(h,p)=>`<div class="page-heading"><a href="#home" class="back">← Back to the garden</a><h1>${h}</h1><p>${p}</p></div>`;
const faces=`<span class="friends" aria-hidden="true">${pip()}${dot()}</span>`;
const trailCount=s=>areas.filter(a=>s.broad.trails[a.id]?.complete).length;

const recoveryReasons={number:'Count the seeds and supplies we saved.',operations:'Arrange equal rows and make enough for our neighbors.',fractions:'Share space and supplies in equal parts.',patterns:'Plan a path with a pattern we can continue.',geometry:'Explore shapes for beds, signs, and shelters.',measurement:'Compare lengths and plan a border.',reasoning:'Check a plan, explain an idea, and try another way.'};
const gardenRequests=[
 {href:'#wonder/estimate-seeds',title:'What did we save?',body:'Pip rescued a seed jar after the storm. Guess what is inside, then open it and count together.',action:'Look inside the seed jar',art:'<rect x="58" y="23" width="84" height="16" rx="5" fill="#866544"/><path d="M64 39H136L145 57V119Q100 137 55 119V57Z" fill="#e2b76e" stroke="#75593c" stroke-width="3"/><rect x="74" y="65" width="52" height="42" rx="5" fill="#fff8e4"/><path d="M100 98V77m0 12q-17 0-14-12 14 0 14 12m0-5q17 0 14-12-14 0-14 12" fill="#397958" stroke="#397958" stroke-width="2"/>'},
 {href:'#wonder/many-rectangles',title:'A bed with room to grow',body:'Moss has room for 24 planting spaces. Help Dot try different rectangular plans. Which would you choose?',action:'Plan a garden bed',art:`<rect x="20" y="35" width="160" height="88" rx="12" fill="#d6b77d" stroke="#75593c" stroke-width="3"/>${Array.from({length:24},(_,i)=>`<circle cx="${30+i%8*20}" cy="${52+Math.floor(i/8)*27}" r="6" fill="#fff8e4" stroke="#397958"/>`).join('')}`},
 {href:'#activities/measurement',title:'How long? How far around?',body:'Before we build, Moss needs ways to compare lengths and borders. Choose a measuring adventure to explore.',action:'Explore lengths and borders',art:'<rect x="45" y="25" width="118" height="70" rx="8" fill="#c9d9bb" stroke="#397958" stroke-width="3" stroke-dasharray="6 4"/><path d="M26 111H178M26 103v16m152-16v16" stroke="#75593c" stroke-width="3"/><path d="M46 111v8m20-8v8m20-8v8m20-8v8m20-8v8m20-8v8m20-8v8" stroke="#75593c" stroke-width="2"/>'}
];
export function broadHome(state,graph,gardenArt,gardenSelection={}) {
  const count=trailCount(state),last=state.broad.journey;
  const resume=last?.active?last.ids[last.index]:areas.find(a=>state.broad.trails[a.id]&&!state.broad.trails[a.id].complete)?.id;
  const story='The storm has passed. Moss wants to bring the garden back. Pip is counting saved seeds. Dot is sketching new beds. Help them make a plan for what could grow here. Choose a request, or wander into any math patch. There is no hurry.';
  return `<section class="hero broad-hero"><div><div class="hello">Number Garden · Planning the garden’s return</div><h1>Count what we have.<br>Plan what can grow.</h1><p class="intro">Moss wants to bring the garden back after the storm. Pip is counting saved seeds. Dot is sketching new beds.<br>Help them make a plan for what could grow here.</p><div class="hero-actions"><a class="primary" href="#wonder/many-rectangles">Help plan a garden bed <span aria-hidden="true">↗</span></a><a class="text-button" href="#checkin">Choose a math walk</a><a class="text-button" href="#activities">Find an adventure</a></div>${hearButton(story,'Hear the garden’s request')}<p class="tiny status-note">One small trail at a time. ${count?`${count} of 7 areas visited.`:'Start wherever you are curious.'}</p></div>${countingGarden(gardenSelection)}</section><section class="garden-requests" aria-labelledby="garden-requests-title"><div class="section-intro"><h2 id="garden-requests-title">On Moss’s planning table</h2><p>Three requests. Pick any one, or follow your own question.</p></div><div class="garden-request-grid">${gardenRequests.map(r=>`<article class="garden-request"><svg viewBox="0 0 200 145" aria-hidden="true">${r.art}</svg><h3>${r.title}</h3><p>${r.body}</p><a class="secondary" href="${r.href}">${r.action}</a></article>`).join('')}</div><p class="tiny">Our counters mark spaces on a pretend planting plan. Real plants need different amounts of room, light, and water.</p><aside class="living-invitation"><h2>Who else needs a place in our garden?</h2><p>Moss wants room for wildlife beside the new beds. Meet a snail, woodlouse or adult butterfly. Compare changing picture clues and find café parcels.</p><a class="secondary" href="#living">Investigate the Living Garden</a></aside></section><section class="resume-strip"><span>Every multiplication fact from 1 × 1 through 12 × 12, with pictures and your choice of practice.</span><a class="primary" href="#facts">Visit the multiplication garden</a></section><section class="paths"><div class="section-intro"><h2>Pick a patch of possibility</h2><p>Every garden is open.</p></div><div class="area-grid">${areas.map(a=>`<article class="area-card" style="--area-color:${color(a.id)}"><span class="area-icon" aria-hidden="true">${areaScene(a.id)}</span><h3>${e(a.name)}</h3><p>${e(a.description)}</p><p class="patch-purpose">${e(recoveryReasons[a.id])}</p><div class="area-actions"><button class="text-button" data-trail="${a.id}">${state.broad.trails[a.id]?.complete?'You visited this garden':state.broad.trails[a.id]?'Continue this trail':'Try two little questions'}</button><a href="#activities/${a.id}">Adventures ↗</a></div></article>`).join('')}</div></section>${resume?`<div class="resume-strip"><span>There’s a trail waiting for you in ${e(areaById(resume).name)}.</span><button class="secondary" data-trail="${resume}">Keep exploring</button></div>`:''}<div class="home-foot"><span><span aria-hidden="true">✦</span> Think out loud. Make a model. Change your mind.</span><a href="#map">Grown-ups: explore the learning connections</a></div>`;
}
export function checkinHub(state) {
  return `${title('A little look around.','Choose an area, sit together, and try two questions. The second question responds to the first. You can stop, skip, or change paths.')}<section class="journey-banner">${faces}<div><h2>A wander through seven gardens</h2><p>Fourteen questions in little pairs, with a stopping place after each pair. There is no need to do them all today.</p></div><button class="primary" id="begin-journey">${state.broad.journey?.active?'Resume our wander':'Explore all seven'}</button></section><div class="area-grid">${areas.map(a=>{const t=state.broad.trails[a.id];return `<article class="area-card"><span class="area-icon" aria-hidden="true">${areaScene(a.id)}</span><h2>${e(a.name)}</h2><p>${e(a.place)} · ${t?.complete?'You visited this garden':t?`${t.index} of 2 recorded`:'Two little questions'}</p><button class="secondary" data-trail="${a.id}">${t?.complete?'See what we noticed':t?'Continue this trail':'Explore this area'}</button></article>`;}).join('')}</div><p class="status-note">This is a small informal sample in each area, not a grade-level test. Drawing, counting, and asking for help are welcome.</p><details class="panel"><summary>Looking for the original multiplication garden walk?</summary><p>Your earlier work is still here, along with the multiplication workshop.</p><a href="#multiplication">Open the multiplication garden walk</a></details>`;
}
export function activityLibrary(state,graph,selected='all') {
  return `${title('Adventures with Pip & Dot.','A short story, an idea to try, a picture you can change, and something to wonder about. Pick whatever looks interesting.')}<div class="level-options" aria-label="Filter activities"><a class="level-choice ${selected==='all'?'selected':''}" href="#activities">All gardens</a>${areas.map(a=>`<a class="level-choice ${selected===a.id?'selected':''}" href="#activities/${a.id}">${e(a.name)}</a>`).join('')}</div>${areas.filter(a=>selected==='all'||a.id===selected).map(a=>{const s=suggestActivity(state,a.id,graph);return `<section class="adventure-section"><div class="section-intro"><h2>${areaScene(a.id)} ${e(a.place)}</h2><a href="#map/${a.checkin[1].topicId}" class="tiny">See the learning connections</a></div><p class="suggestion-reason">${e(s.reason.replaceAll('check-in','garden walk'))} <button class="text-button" data-adventure="${s.item.id}">Try ${e(s.item.title)}</button></p><div class="adventure-grid">${a.activities.map(q=>`<article class="adventure-card"><span class="tag">${q.tier==='support'?'Build an idea':q.tier==='stretch'?'Explore further':'Make a connection'}</span><h3>${e(q.title)}</h3><p>${e(q.prompt)}</p><button class="secondary" data-adventure="${q.id}">Try this adventure</button></article>`).join('')}</div></section>`;}).join('')}<section class="panel"><h2>A little multiplication, too</h2><p>The original six-fact practice sets and puzzles are still available.</p><div class="summary-links"><a href="#practice" class="secondary">Multiplication workshop</a><a href="#puzzles" class="secondary">Original puzzles</a></div></section>`;
}
export function trailSummary(state,id,graph) {
  const a=areaById(id), t=state.broad.trails[id], obs=areaEvidence(state,id).slice(-Math.min(2,t?.index||0)), s=suggestActivity(state,id,graph), j=state.broad.journey;
  const next=j?.active&&j.ids[j.index]===id&&j.index<j.ids.length-1;
  return `${title('A few things we noticed.','Two questions give us ideas for what to try next. They don’t define what you can do in this whole area.')}<section class="summary-callout"><h2>${areaScene(a.id)} ${e(a.name)}</h2>${obs.map(o=>`<p><strong>${e(o.label)}:</strong> ${e(broadDescribe(o))}.</p>`).join('')}<p class="tiny">New numbers, a different representation, and another day can tell us more.</p></section><div class="notes-grid"><section class="panel"><h2>One possible next adventure</h2><h3>${e(s.item.title)}</h3><p>${e(s.reason.replaceAll('check-in','garden walk'))}</p><button class="primary" data-adventure="${s.item.id}">Try this adventure</button></section><section class="panel"><h2>Where shall we wander?</h2><div class="summary-links">${next?'<button class="primary" id="next-garden">Visit the next garden</button>':''}<a class="secondary" href="#activities">Choose any adventure</a><a href="#map/${a.checkin[1].topicId}" class="secondary">See the map</a><a href="#home" class="text-button">Finish for now</a></div><button class="text-button" data-revisit="${id}">Try another garden walk here</button></section></div>`;
}
export function broadObservationDetails(o) {
  const labels=o.attempts.map(n=>o.choices?.[n]??n);
  return `<div class="evidence-item"><strong>${e(o.label)} — ${e(broadDescribe(o))}</strong><p>${e(o.prompt)}</p><p>${o.status==='skipped'?'Skipped.':`Answers tried: ${e(labels.join(', ')||'None')}.`}${o.hinted?' Hint used.':''}${o.modelUsed?' Picture playground used.':''}${o.revealed?' Worked solution opened.':''}${o.stepsSeen?' Partial steps opened.':''}${o.helpUsed?` Smaller example used; its separate attempts: ${e(Array.isArray(o.helper?.attempts)?o.helper.attempts.join(', ')||'none':'none')}.`:''}${Number.isInteger(o.supportLevel)?` Explicit support level: ${o.supportLevel}.`:''}${o.sameKind?' New numbers in a familiar kind of question.':''}${Array.isArray(o.misconceptions)?o.misconceptions.map(m=>` Tried ${e(m.value)}: ${e(m.label)}.`).join(''):''}${o.source==='activity'?' After a teaching activity.':''}${o.familiar?' This question appeared earlier.':''}${o.knownFact?' This fact appeared earlier.':''}${o.priorExposureUnknown?' Earlier familiarity was not recorded.':''}</p></div>`;
}
export function closedDraftNotes(state){
 const records=state.broad.closedDrafts||[];if(!records.length)return '';
 return `<details class="panel"><summary>Earlier paused work (${records.length} kept)</summary><p>These saved questions could not be resumed. Their original work is kept below and in the notes download. It is not scored against a replacement question or used for learning suggestions.</p>${records.map(({key,draft})=>`<div class="evidence-item"><strong>${e(typeof draft.question?.title==='string'?draft.question.title:key)}</strong><p>${e(typeof draft.question?.prompt==='string'?draft.question.prompt:'The earlier question could not be read.')}</p><p>Earlier answers tried: ${e(JSON.stringify(draft.attempts??[]))}. Unsubmitted input: ${e(typeof draft.input==='string'?draft.input:'')}.</p><p>${draft.hinted?'Hint used. ':''}${draft.helpUsed?'Smaller example used. ':''}${draft.revealed?'Worked solution opened. ':''}This is kept work, not a completed observation.</p></div>`).join('')}</details>`;
}
export function broadNotes(state,graph) {
  return `${closedDraftNotes(state)}<section class="panel"><h2>Our wider math explorations</h2><p class="tiny">Observations belong to the individual tasks. They do not establish mastery of a topic or its prerequisites.</p>${areas.map(a=>{const obs=areaEvidence(state,a.id);return `<div class="skill-row"><strong>${areaScene(a.id)} ${e(a.name)}</strong>${obs.length?obs.slice(-2).map(o=>`<p>${e(o.label)}: ${e(broadDescribe(o))}.</p>`).join(''):'<p>Not explored yet.</p>'}<div class="area-actions"><button class="text-button" data-trail="${a.id}">Visit this area</button><a href="#map/${a.checkin[1].topicId}">Learning connections ↗</a></div></div>`;}).join('')}</section><details class="panel"><summary>Wider check-in details (${state.broad.observations.length} recorded)</summary>${state.broad.observations.map(broadObservationDetails).join('')||'<p>No wider check-in questions recorded yet.</p>'}</details><details class="panel"><summary>Adventure details (${state.broad.activityObservations.length} recorded)</summary><p class="tiny">These are learning attempts after explanations, kept separate from check-in observations.</p>${state.broad.activityObservations.map(broadObservationDetails).join('')||'<p>No adventures recorded yet.</p>'}</details>`;
}
export function learningMap(state,graph,selected) {
  if(!graph)return `${title('The learning connections','The map is unavailable right now. The check-ins and adventures still work.')}<a href="#checkin">Choose a check-in</a>`;
  const nodes=new Map(graph.topics.map(t=>[t.id,t])), first=areas[0].checkin[1].topicId, node=nodes.get(selected)||nodes.get(first);
  const incoming=graph.dependencies.filter(d=>d.topicId===node.id), outgoing=graph.dependencies.filter(d=>d.prerequisiteId===node.id);
  const obs=[...state.broad.observations,...state.broad.activityObservations].filter(o=>o.topicId===node.id);
  const activities=areas.flatMap(a=>a.activities).filter(q=>q.topicId===node.id);
  const matches=placeMatches(node.id);
  const link=(d,id)=>`<li><a href="#map/${id}">${e(nodes.get(id)?.name||id)}</a><span class="edge-kind">${d.strength==='hard'?'Foundation link':'Helpful link'}</span><p>${e(d.reason)}</p></li>`;
  return `${title('How the ideas connect.','A parent-facing slice of Marble’s map, with our local observations alongside. A connection is a teaching suggestion, never a locked gate.')}<div class="map-area-links">${areas.map(a=>`<a href="#map/${a.checkin[1].topicId}">${areaScene(a.id)} ${e(a.name)}</a>`).join('')}</div><p><a href="#explore">Visit connected adventures across subjects</a></p><div class="map-area-links">${learningPlaces.flatMap(p=>p.topics.map(t=>`<a href="#map/${t.id}">${e(nodes.get(t.id)?.name||t.id)}</a>`)).join('')}</div><div class="map-focus"><div class="map-branch"><h2>Builds on</h2><ul>${incoming.map(d=>link(d,d.prerequisiteId)).join('')||'<li>No prerequisite links are included here.</li>'}</ul></div><section class="map-center"><span class="tag">${e(node.domain)}</span><h2>${e(node.name)}</h2><p>${e(node.description)}</p><p class="tiny">${node.focus?'Linked to a math check-in or adventure here.':matches.length?'Partly connected to guided practice here; read its scope below.':'Context concept: no playable activity is attached here.'}</p>${matches.map(p=>`<p><a class="secondary" href="${p.href}">${e(p.title)}</a></p><p class="tiny">${e(p.scope)}</p>`).join('')}<h3>Recorded math-task observations</h3>${obs.length?obs.map(o=>`<p class="map-observation">${e(o.label)}: ${e(broadDescribe(o))}${o.source==='activity'?' (after teaching)':''}.</p>`).join(''):'<p>No observations for this concept yet.</p>'}${activities.map(q=>`<button class="secondary" data-adventure="${q.id}">${e(q.title)}</button>`).join('')}<p class="tiny status-note">${node.outsidePrerequisites?`${node.outsidePrerequisites} further direct prerequisite link(s) lie outside this slice. `:''}Nothing here infers that other connected concepts have been mastered.</p></section><div class="map-branch"><h2>Connects next</h2><ul>${outgoing.map(d=>link(d,d.topicId)).join('')||'<li>No next links are included here.</li>'}</ul></div></div><details class="panel"><summary>About this map & open data</summary><p>We use ${graph.topics.length} concepts from Marble’s ${graph.totalTopics}-concept v1 map. Math task links, limited science/reading activity matches and their direct prerequisites are included; further branches may be outside this slice. Names can be broader than the example we sampled.</p><p>Marble Skill Taxonomy v1 © Generative Spark, Inc. (Marble). This subset and its relationships are shared under ODbL 1.0; Marble’s descriptive text and link reasons are CC BY-SA 4.0. The activities are original.</p><p><a href="./marble-map.json" download>Download this map data</a> · <a href="https://github.com/withmarbleapp/os-taxonomy/tree/${graph.commit}" target="_blank" rel="noopener">Pinned source</a> · <a href="https://opendatacommons.org/licenses/odbl/1-0/" target="_blank" rel="noopener">Database license</a> · <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">Content license</a></p><p>The map data download contains curriculum data only. Device-local observations are exported separately from Grown-up notes.</p></details>`;
}
export const shapeVertices=(shape,turns=0)=>{
 const base=shape==='triangle'?Array.from({length:3},(_,i)=>{const a=(-90+i*120)*Math.PI/180;return [100+78*Math.cos(a),100+78*Math.sin(a)];}):shape==='hexagon'?Array.from({length:6},(_,i)=>{const a=(-90+i*60)*Math.PI/180;return [100+78*Math.cos(a),100+78*Math.sin(a)];}):shape==='square'?[[35,35],[165,35],[165,165],[35,165]]:[[20,50],[180,50],[180,150],[20,150]];
 const a=turns*Math.PI/2;return base.map(([x,y])=>[100+(x-100)*Math.cos(a)-(y-100)*Math.sin(a),100+(x-100)*Math.sin(a)+(y-100)*Math.cos(a)]);
};
export function foldChoices(m){
 const base=m.shape==='triangle'?[[90,'Through one corner'],[30,'Through another corner'],[150,'Through the third corner'],[0,'Try a sideways fold']]:m.shape==='hexagon'?[0,30,60,90,120,150].map((a,i)=>[a,`Try fold ${i+1}`]):m.shape==='square'?[[0,'Top to bottom'],[90,'Side to side'],[45,'Corner to corner'],[135,'Other corners']]:[[0,'Top to bottom'],[90,'Side to side'],[Math.atan2(50,80)*180/Math.PI,'Corner to corner'],[180-Math.atan2(50,80)*180/Math.PI,'Other corners']];
 return base.map(([angle,label])=>({angle:(angle+(m.turns||0)*90)%180,label}));
}
export function foldGeometry(shape,turns,angle){
 const original=shapeVertices(shape,turns),a=angle*Math.PI/180,dx=Math.cos(a),dy=Math.sin(a);
 const side=([x,y])=>-(x-100)*dy+(y-100)*dx,source=[];
 for(let i=0;i<original.length;i++){
  const p=original[i],q=original[(i+1)%original.length],sp=side(p),sq=side(q);
  if(sp>=-1e-8)source.push(p);
  if((sp>1e-8&&sq< -1e-8)||(sp< -1e-8&&sq>1e-8)){const t=sp/(sp-sq);source.push([p[0]+t*(q[0]-p[0]),p[1]+t*(q[1]-p[1])]);}
 }
 const reflect=([x,y])=>{const dot=(x-100)*dx+(y-100)*dy;return [100+2*dot*dx-(x-100),100+2*dot*dy-(y-100)];};
 return {original,source,reflected:source.map(reflect),line:[[100-100*dx,100-100*dy],[100+100*dx,100+100*dy]]};
}
const points=p=>p.map(([x,y])=>`${x.toFixed(3)},${y.toFixed(3)}`).join(' ');
const itemNames={seed:'seeds',berry:'berries',cup:'cups',cracker:'crackers',muffin:'muffins',button:'buttons',pebble:'pebbles',tile:'tiles',flower:'flowers'};
export function modelCaption(m){
 if(m.type==='place')return `Pip built ${m.hundreds||0} hundreds, ${m.tens||0} tens and ${m.ones||0} ones.`;
 if(m.type==='array')return `Pip arranged ${m.rows} rows of ${m.cols} ${itemNames[m.item]||'seeds'}.`;
 if(m.type==='fraction')return `Pip shaded ${m.shaded} of ${m.parts} equal pieces.`;
 if(m.type==='pattern')return `Pip starts at ${m.values[0]} and ${m.step<0?'subtracts':'adds'} ${Math.abs(m.step)} each time.`;
 if(m.type==='shape')return `Pip is exploring ${m.shape==='hexagon'?'a regular hexagon':m.shape==='triangle'?'an equilateral triangle':`a ${m.shape}`}.`;
 if(m.type==='compass')return `Pip starts facing north. Try a quarter turn.`;
 if(m.type==='ruler')return `Pip put a ribbon between marks ${m.start} and ${m.end}.`;
 return `Pip set out ${m.count||0} ${itemNames[m.item]||'seeds'}.`;
}
export function renderModel(q,active,editable=false,context={}) {
 const m=active.model||q.model;if(!m)return '';
 const checkin=context.mode==='checkin',reveal=!checkin||active.modelTotalShown||active.revealed;
 const button=(action,label,disabled=false,extra='')=>`<button type="button" class="model-button" data-model-action="${action}" ${disabled?'disabled':''} ${extra}>${label}</button>`;
 const tap=(action,label,inner,cls='',extra='')=>`<button type="button" class="model-tap ${cls}" data-model-action="${action}" aria-label="${e(label)}" ${extra}>${inner}</button>`;
 const item=Object.hasOwn(itemNames,m.item)?m.item:'seed';
 let visual='',controls='',readout='',total=false;
 if(m.type==='place'){
  visual=`<div class="place-board" role="group" aria-label="Hundreds, tens and ones">${[['hundreds','100','hundred'],['tens','10','ten'],['ones','1','one']].map(([k,v,name])=>`<div><span>${k}</span><div class="place-tokens">${Array.from({length:m[k]||0},()=>editable?tap(`${name}-remove`,`Remove one ${name}`,v,'place-token'):`<i>${v}</i>`).join('')||'<em>—</em>'}</div>${editable?tap(`${name}-add`,`Add one ${name}`,'+','token-tray',m[k]>=(k==='hundreds'?9:k==='tens'?12:20)?'disabled':''):''}</div>`).join('')}</div>`;
  readout=reveal?`${(m.hundreds||0)*100+(m.tens||0)*10+(m.ones||0)} altogether`:`${m.hundreds||0} hundreds, ${m.tens||0} tens, ${m.ones||0} ones`;total=true;
  controls=button('hundred-add','Add a hundred',m.hundreds>=9)+button('hundred-remove','Remove a hundred',!m.hundreds)+button('ten-add','Add a ten',m.tens>=12)+button('ten-remove','Remove a ten',!m.tens)+button('one-add','Add a one',m.ones>=20)+button('one-remove','Remove a one',!m.ones)+button('trade','Trade 10 ones for a ten',(m.ones||0)<10||m.tens>=12)+button('trade-tens','Trade 10 tens for a hundred',m.tens<10||m.hundreds>=9);
 }else if(m.type==='array'){
  const selected=new Set(m.counted||[]);
  visual=objectSymbols()+`<div class="model-array direct-array" role="group" aria-label="${m.rows} rows, ${m.cols} in each" style="--array-cols:${m.cols}">${Array.from({length:m.rows*m.cols},(_,i)=>editable?tap(`count-${i}`,`Count ${itemNames[item]} in row ${Math.floor(i/m.cols)+1}, column ${i%m.cols+1}`,itemGlyph(item)+(selected.has(i)?`<b>${[...selected].indexOf(i)+1}</b>`:''),'array-dot',`aria-pressed="${selected.has(i)}"`):itemGlyph(item)).join('')}</div>${editable?`<div class="array-grow">${button('row-add','+ Ghost row',m.rows>=9)}${button('col-add','+ Ghost column',m.cols>=9)}</div>`:''}`;
  readout=reveal?`${m.rows} rows × ${m.cols} in each = ${m.rows*m.cols}`:`${m.rows} rows, ${m.cols} in each`;total=true;
  if(selected.size)readout+=` · You counted ${selected.size}`;
  controls=button('row-add','Add a row',m.rows>=9)+button('row-remove','Remove a row',m.rows<=1)+button('col-add','Add a column',m.cols>=9)+button('col-remove','Remove a column',m.cols<=1)+button('rotate','Turn the array');
 }else if(m.type==='fraction'){
  const selected=new Set(m.shadedPieces||Array.from({length:m.shaded},(_,i)=>i));
  visual=`<div class="fraction-bar direct-fractions" role="group" aria-label="One whole divided into ${m.parts} equal pieces" style="grid-template-columns:repeat(${m.parts},1fr)">${Array.from({length:m.parts},(_,i)=>editable?tap(`fraction-toggle-${i}`,`Piece ${i+1}, ${selected.has(i)?'shaded':'unshaded'}`,'',selected.has(i)?'shaded':'',`aria-pressed="${selected.has(i)}"`):`<span class="${selected.has(i)?'shaded':''}"></span>`).join('')}</div>`;
  readout=reveal?`${m.shaded}/${m.parts} of the same whole is shaded`:'Equal pieces of the same whole; compare the shaded and unshaded pieces.';total=true;
  controls=button('shade-add','Shade one more',m.shaded>=m.parts)+button('shade-remove','Shade one fewer',m.shaded<=0)+button('parts-add','Add a piece',m.parts>=12)+button('parts-remove','Remove a piece',m.parts<=2);
 }else if(m.type==='pattern'){
  visual=`<div class="pattern-tiles" role="group" aria-label="Pattern: ${m.values.join(', ')}">${m.values.map(v=>`<span>${v}</span>`).join('')}${editable?button('pattern-next','+ Next stone',m.values.length>=10):''}</div>`;
  readout=`The same jump each time: ${m.step>=0?'+':''}${m.step}`;
  controls=button('pattern-next','Add the next step',m.values.length>=10)+button('pattern-back','Remove the last step',m.values.length<=2);
 }else if(m.type==='shape'){
  const original=points(shapeVertices(m.shape,m.turns||0)),fold=Number.isFinite(m.foldAngle)?foldGeometry(m.shape,m.turns||0,m.foldAngle):null;
  visual=`<svg class="shape-model" viewBox="-10 -10 220 220" role="img" aria-label="${checkin&&!reveal&&(q.params?.type==='shapeName'||q.id==='geometry-foundation')?({triangle:'A closed shape with three equal straight sides',square:'A closed shape with four equal sides and four right angles',rectangle:'A closed shape with four right angles and equal opposite sides, longer than it is wide',hexagon:'A closed shape with six equal sides and six equal angles'}[m.shape]):e(m.shape)}${fold?', with a chosen fold; pink shows a part that misses the starting shape':''}"><polygon points="${original}" fill="#e9b84a" stroke="#183f39" stroke-width="2"/>${fold?`<defs><mask id="broad-fold-outside"><rect x="-100" y="-100" width="400" height="400" fill="white"/><polygon points="${original}" fill="black"/></mask></defs><polygon points="${points(fold.source)}" fill="#fff3db" opacity=".7"/><polygon points="${points(fold.reflected)}" fill="#75a183" fill-opacity=".65" stroke="#397958" stroke-width="2"/><polygon points="${points(fold.reflected)}" fill="#da8d8d" stroke="#9f4d51" stroke-width="2" mask="url(#broad-fold-outside)"/><path d="M${fold.line[0].join(' ')}L${fold.line[1].join(' ')}" stroke="#183f39" stroke-width="2" stroke-dasharray="5 4"/>`:''}</svg>${editable?button('turn','↻ Quarter turn'):''}`;
  const turns=m.turns||0;readout=`${turns} quarter ${turns===1?'turn':'turns'} clockwise from the starting picture${fold?'. The pale half folds across the dashed line. Pink shows any part that misses.':''}`;
  controls=button('turn','Make a quarter turn')+button('change-shape','Try another shape')+`<fieldset class="fold-controls"><legend>Try a fold</legend>${foldChoices(m).map((choice,i)=>button(`fold-angle-${i}`,choice.label,false,`aria-pressed="${m.foldAngle===choice.angle}"`)).join('')}</fieldset>`;
 }else if(m.type==='compass'){
  const turns=((m.turns||0)%4+4)%4,direction=['north','east','south','west'][turns];
  visual=`<svg class="compass-model" viewBox="0 0 210 210" role="img" aria-label="Compass with north at the top${reveal?`; Pip faces ${direction}`:' and a turning arrow'}"><circle cx="105" cy="105" r="77" fill="#fffdf4" stroke="#183f39" stroke-width="2"/><g font-size="17" text-anchor="middle" fill="#183f39"><text x="105" y="21">N</text><text x="195" y="111">E</text><text x="105" y="204">S</text><text x="15" y="111">W</text></g><path d="M105 80V38m0 0l-8 12m8-12l8 12" transform="rotate(${turns*90} 105 105)" stroke="#b93e2c" stroke-width="4" fill="none"/><g transform="translate(76 77) scale(.5)">${pip('think').replace(/<svg[^>]*>|<\/svg>/g,'')}</g></svg>`;
  readout=reveal?`Pip faces ${direction}. ${turns} quarter ${turns===1?'turn':'turns'} clockwise from north.`:'Start facing north. Watch the arrow as Pip turns.';total=true;
  controls=button('compass-cw','Turn clockwise')+button('compass-ccw','Turn counterclockwise');
 }else if(m.type==='ruler'){
  const x=n=>20+n/m.max*300;
  visual=`<svg class="ruler-model" viewBox="0 0 340 105" role="img" aria-label="Ruler with ribbon ends at ${m.start} and ${m.end} centimeters"><path d="M20 64H320" stroke="#183f39" stroke-width="2"/><rect x="${x(m.start)}" y="22" width="${x(m.end)-x(m.start)}" height="23" fill="#e9b84a"/>${Array.from({length:m.max+1},(_,n)=>`<path d="M${x(n)} 58v${n%5?10:16}" stroke="#183f39"/>${n%5===0||n===m.start||n===m.end?`<text x="${x(n)}" y="94" text-anchor="middle" font-size="12">${n}</text>`:''}`).join('')}</svg>${editable?`<div class="ruler-mark-controls" role="group" aria-label="Tap a ruler mark to move the nearer ribbon end">${Array.from({length:m.max+1},(_,n)=>button(`ruler-mark-${n}`,String(n))).join('')}</div>`:''}`;
  readout=reveal?`From ${m.start} to ${m.end}: ${m.end-m.start} centimeters long`:`The ribbon’s ends are at ${m.start} and ${m.end} centimeters`;total=true;
  controls=button('start-left','Move start left',m.start<=0)+button('start-right','Move start right',m.start>=m.end)+button('end-left','Move end left',m.end<=m.start)+button('end-right','Move end right',m.end>=m.max);
 }else{
  visual=objectSymbols()+`<div class="counter-model direct-counters" role="group" aria-label="A collection of ${itemNames[item]}">${Array.from({length:Math.min(40,m.count||0)},()=>editable?tap('counter-remove',`Remove one ${itemNames[item]}`,itemGlyph(item)):itemGlyph(item)).join('')}${editable?tap('counter-add',`Add one ${itemNames[item]}`,'+','token-tray',m.count>=40?'disabled':''):''}</div>`;
  readout=reveal?`${m.count||0} ${itemNames[item]}`:'A collection to count or rearrange';total=true;controls=button('counter-add','Add a counter',m.count>=40)+button('counter-remove','Remove a counter',m.count<=0);
 }
 return `<section class="picture-playground" aria-label="${checkin?'Picture playground':"Pip's example"}" tabindex="-1">${!checkin?`<h3>Pip’s example</h3><p class="model-caption">${e(modelCaption(m))}</p>`:''}${visual}${editable?`<p class="model-readout" aria-live="polite">${readout}</p><div class="model-controls">${controls}${checkin&&total&&!reveal?button('show-total','Show the total'):''}${button('reset','Reset the picture')}</div><p class="tiny">${checkin?'Change this picture to explore. The question keeps its own numbers.':'This is Pip’s example. Change it to explore. Your turn uses new numbers.'}</p>`:''}</section>`;
}
export function adjustModel(q,active,action) {
 active.model??=structuredClone(q.model);const m=active.model;
 if(action==='show-total'){active.modelTotalShown=true;return;}
 if(action==='reset'){active.model=structuredClone(q.model);return;}
 if(m.type==='place'){
  if(action==='hundred-add')m.hundreds=Math.min(9,(m.hundreds||0)+1);if(action==='hundred-remove')m.hundreds=Math.max(0,(m.hundreds||0)-1);
  if(action==='ten-add')m.tens=Math.min(12,(m.tens||0)+1);if(action==='ten-remove')m.tens=Math.max(0,(m.tens||0)-1);
  if(action==='one-add')m.ones=Math.min(20,(m.ones||0)+1);if(action==='one-remove')m.ones=Math.max(0,(m.ones||0)-1);
  if(action==='trade'&&m.ones>=10&&m.tens<12){m.ones-=10;m.tens++;}if(action==='trade-tens'&&m.tens>=10&&m.hundreds<9){m.tens-=10;m.hundreds++;}
 }else if(m.type==='array'){
  if(action==='row-add')m.rows=Math.min(9,m.rows+1);if(action==='row-remove')m.rows=Math.max(1,m.rows-1);if(action==='col-add')m.cols=Math.min(9,m.cols+1);if(action==='col-remove')m.cols=Math.max(1,m.cols-1);if(action==='rotate')[m.rows,m.cols]=[m.cols,m.rows];
  const match=/^count-(\d+)$/.exec(action);if(match){const n=Number(match[1]);if(n<m.rows*m.cols){m.counted??=[];m.counted=m.counted.includes(n)?m.counted.filter(v=>v!==n):[...m.counted,n];}}else m.counted=[];
 }else if(m.type==='fraction'){
  let pieces=m.shadedPieces||Array.from({length:m.shaded},(_,i)=>i);const match=/^fraction-toggle-(\d+)$/.exec(action);
  if(match){const n=Number(match[1]);if(n<m.parts)pieces=pieces.includes(n)?pieces.filter(v=>v!==n):[...pieces,n];}
  if(action==='shade-add'&&pieces.length<m.parts)pieces.push(Array.from({length:m.parts},(_,i)=>i).find(n=>!pieces.includes(n)));
  if(action==='shade-remove')pieces.pop();if(action==='parts-add')m.parts=Math.min(12,m.parts+1);if(action==='parts-remove')m.parts=Math.max(2,m.parts-1);
  m.shadedPieces=pieces.filter(n=>n<m.parts);m.shaded=m.shadedPieces.length;
 }else if(m.type==='pattern'){
  if(action==='pattern-next'&&m.values.length<10)m.values.push(m.values.at(-1)+m.step);if(action==='pattern-back'&&m.values.length>2)m.values.pop();
 }else if(m.type==='shape'){
  if(action==='turn'){m.turns=((m.turns||0)+1)%4;delete m.foldAngle;}if(action==='change-shape'){const all=['triangle','rectangle','square','hexagon'];m.shape=all[(all.indexOf(m.shape)+1)%4];delete m.foldAngle;}
  const match=/^fold-angle-(\d+)$/.exec(action);if(match){const choice=foldChoices(m)[Number(match[1])];if(choice)m.foldAngle=choice.angle;}
 }else if(m.type==='compass'){
  if(action==='compass-cw')m.turns=((m.turns||0)+1)%4;if(action==='compass-ccw')m.turns=((m.turns||0)+3)%4;
 }else if(m.type==='ruler'){
  if(action==='start-left')m.start=Math.max(0,m.start-1);if(action==='start-right')m.start=Math.min(m.end,m.start+1);if(action==='end-left')m.end=Math.max(m.start,m.end-1);if(action==='end-right')m.end=Math.min(m.max,m.end+1);
  const match=/^ruler-mark-(\d+)$/.exec(action);if(match){const n=Number(match[1]);if(n<=m.max){if(Math.abs(n-m.start)<=Math.abs(n-m.end))m.start=Math.min(n,m.end);else m.end=Math.max(n,m.start);}}
 }else{if(action==='counter-add')m.count=Math.min(40,m.count+1);if(action==='counter-remove')m.count=Math.max(0,m.count-1);}
}

function color(id){return {number:'#e9b84a',operations:'#d8e8dc',fractions:'#f1d9d4',patterns:'#dce6f1',geometry:'#e3def2',measurement:'#d8ebe8',reasoning:'#f3e4bc'}[id]||'#eaf4ef';}
